const body = $json.body || {};
const required = (name) => { const value = String(body[name] ?? '').trim(); if (!value) throw new Error('Missing ' + name); return value; };
const action = required('action');
const actorEmail = required('actor_email').toLowerCase();
if (!/^[^\s@]+@apexdp\.com$/i.test(actorEmail)) throw new Error('Administrator identity must be an Apex Workspace account.');
const idempotencyKey = required('idempotency_key');
if (!/^[A-Za-z0-9_-]{16,100}$/.test(idempotencyKey)) throw new Error('Invalid idempotency key.');
if (action === 'approve_for_doctor') {
  const reason = required('reason');
  if (reason.length < 12 || reason.length > 2000) throw new Error('Approval evidence must be 12–2000 characters.');
  return [{ json: { action, actor_email: actorEmail, idempotency_key: idempotencyKey, article_id: required('article_id'), campaign_id: required('campaign_id'), doctor_id: required('doctor_id'), expected_status: required('expected_status'), expected_version: Number(body.expected_version), reason } }];
}
if (action === 'launch_campaign') {
  const topics = Array.isArray(body.topics) ? body.topics.map((topic) => ({ title: String(topic?.title || '').trim() })) : [];
  const doctorIds = Array.isArray(body.doctor_ids) ? [...new Set(body.doctor_ids.map((id) => String(id).trim()).filter(Boolean))] : [];
  const campaignName = required('campaign_name');
  const month = required('campaign_month');
  if (!/^\d{4}-\d{2}$/.test(month) || topics.length !== 3 || topics.some((topic) => !topic.title) || new Set(topics.map((topic) => topic.title.toLowerCase())).size !== 3 || !doctorIds.length) throw new Error('Campaign month, three distinct topics, and at least one doctor are required.');
  const slug = campaignName.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 48);
  const campaignId = 'campaign_' + month.replace('-', '') + '_' + slug;
  return [{ json: { action, actor_email: actorEmail, idempotency_key: idempotencyKey, campaign_id: campaignId, campaign_name: campaignName, campaign_month: month + '-01', practice_id: required('practice_id'), topics_json: JSON.stringify(topics), doctor_ids_json: JSON.stringify(doctorIds) } }];
}
throw new Error('Unsupported administrative action.');

