CREATE TABLE IF NOT EXISTS `apex-marketing-n8n.automated_article_creation.admin_commands` (
  idempotency_key STRING NOT NULL, action STRING NOT NULL, actor_email STRING NOT NULL,
  entity_id STRING NOT NULL, requested_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, payload JSON
);
ASSERT NOT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.admin_commands` WHERE idempotency_key = @idempotency_key) AS 'This command was already processed.';
ASSERT (SELECT COUNT(*) FROM `apex-marketing-n8n.automated_article_creation.articles` WHERE article_id = @article_id AND campaign_id = @campaign_id AND doctor_id = @doctor_id AND status = @expected_status AND current_version = CAST(@expected_version AS INT64)) = 1 AS 'The article changed or is no longer waiting for doctor approval.';
BEGIN TRANSACTION;
UPDATE `apex-marketing-n8n.automated_article_creation.approvals` SET status = 'APPROVED', responded_at = CURRENT_TIMESTAMP(), response = @reason
WHERE article_id = @article_id AND approval_type = 'DOCTOR_REVIEW' AND status = 'PENDING';
UPDATE `apex-marketing-n8n.automated_article_creation.article_review_links` SET status = 'SUPERSEDED', responded_at = CURRENT_TIMESTAMP()
WHERE article_id = @article_id AND status IN ('READY', 'OPENED');
UPDATE `apex-marketing-n8n.automated_article_creation.articles` SET status = 'DOCTOR_APPROVED', doctor_approved_at = CURRENT_TIMESTAMP()
WHERE article_id = @article_id AND status = @expected_status AND current_version = CAST(@expected_version AS INT64);
UPDATE `apex-marketing-n8n.automated_article_creation.campaign_doctors` SET status = 'DOCTOR_APPROVED', updated_at = CURRENT_TIMESTAMP()
WHERE campaign_id = @campaign_id AND doctor_id = @doctor_id;
INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (GENERATE_UUID(), 'article', @article_id, 'doctor.approved_by_admin', CURRENT_TIMESTAMP(), 'admin_dashboard', NULL,
  TO_JSON(STRUCT(@actor_email AS actor_email, @reason AS evidence, CAST(@expected_version AS INT64) AS version_number, @idempotency_key AS idempotency_key)));
INSERT INTO `apex-marketing-n8n.automated_article_creation.admin_commands`
(idempotency_key, action, actor_email, entity_id, requested_at, completed_at, payload)
VALUES (@idempotency_key, 'approve_for_doctor', @actor_email, @article_id, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(),
  TO_JSON(STRUCT(@campaign_id AS campaign_id, @doctor_id AS doctor_id, @reason AS evidence, CAST(@expected_version AS INT64) AS version_number)));
COMMIT TRANSACTION;
SELECT TRUE AS ok, 'DOCTOR_APPROVED' AS status, @article_id AS article_id;

CREATE TABLE IF NOT EXISTS `apex-marketing-n8n.automated_article_creation.admin_commands` (
  idempotency_key STRING NOT NULL, action STRING NOT NULL, actor_email STRING NOT NULL,
  entity_id STRING NOT NULL, requested_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, payload JSON
);
ASSERT NOT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.admin_commands` WHERE idempotency_key = @idempotency_key) AS 'This command was already processed.';
ASSERT NOT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.campaigns` WHERE campaign_id = @campaign_id) AS 'This campaign already exists.';
ASSERT (SELECT COUNT(*) FROM `apex-marketing-n8n.automated_article_creation.practices` WHERE practice_id = @practice_id AND active = TRUE) = 1 AS 'The selected practice is not active.';
ASSERT (SELECT COUNT(*) FROM `apex-marketing-n8n.automated_article_creation.doctors` WHERE doctor_id IN UNNEST(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json))) AND practice_id = @practice_id AND active = TRUE) = ARRAY_LENGTH(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json))) AS 'Every selected doctor must be active at the selected practice.';
ASSERT ARRAY_LENGTH(JSON_QUERY_ARRAY(PARSE_JSON(@topics_json))) = 3 AS 'Exactly three topics are required.';
BEGIN TRANSACTION;
INSERT INTO `apex-marketing-n8n.automated_article_creation.campaigns`
(campaign_id, campaign_name, campaign_month, status, doctor_review_days, require_marketing_approval, created_at, launched_at)
VALUES (@campaign_id, @campaign_name, DATE(@campaign_month), 'LAUNCHED', 5, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP());
INSERT INTO `apex-marketing-n8n.automated_article_creation.campaign_topics`
(topic_id, campaign_id, topic_title, topic_description, interview_guidance, topic_sort_order, active, created_at)
SELECT CONCAT(@campaign_id, '_topic_', CAST(offset + 1 AS STRING)), @campaign_id, JSON_VALUE(topic, '$.title'), JSON_VALUE(topic, '$.title'), NULL, offset + 1, TRUE, CURRENT_TIMESTAMP()
FROM UNNEST(JSON_QUERY_ARRAY(PARSE_JSON(@topics_json))) topic WITH OFFSET;
INSERT INTO `apex-marketing-n8n.automated_article_creation.campaign_doctors`
(campaign_id, doctor_id, status, invited_at, created_at, updated_at)
SELECT @campaign_id, doctor_id, 'READY', NULL, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()
FROM UNNEST(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json))) doctor_id;
INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (GENERATE_UUID(), 'campaign', @campaign_id, 'campaign.started_by_admin', CURRENT_TIMESTAMP(), 'admin_dashboard', NULL,
  TO_JSON(STRUCT(@actor_email AS actor_email, @practice_id AS practice_id, @idempotency_key AS idempotency_key)));
INSERT INTO `apex-marketing-n8n.automated_article_creation.admin_commands`
(idempotency_key, action, actor_email, entity_id, requested_at, completed_at, payload)
VALUES (@idempotency_key, 'launch_campaign', @actor_email, @campaign_id, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(),
  TO_JSON(STRUCT(@practice_id AS practice_id, @topics_json AS topics_json, @doctor_ids_json AS doctor_ids_json)));
COMMIT TRANSACTION;
SELECT TRUE AS ok, 'LAUNCHED' AS status, @campaign_id AS campaign_id;
